 $('#pagesViewport').addEventListener('input',e=>{if(state.rendering)return;const editor=e.target.closest?.('.farast-editor');if(!editor)return;editor.dataset.empty=editor.textContent.trim()?'false':'true';if(!state.inputBeforeModel)state.inputBeforeModel=cloneModel(state.model);syncEditorFromDom(editor);state.selection=getSelectionInfo();clearTimeout(state.historyTimer);state.historyTimer=setTimeout(()=>{const before=state.inputBeforeModel||cloneModel(state.model);captureModel();commitHistory(before,cloneModel(state.model),'ویرایش متن');state.inputBeforeModel=null;state.dirty=true;scheduleSave();updateStats()},450)});
